/* ================= LANGUES (lang.js) : 12 langues, chargé avant app.js =================
   - LANG_META : code → { name : nom natif, locale : pour fmt() }
   - I18N      : code → { clé : texte } ; « {0} », « {1} » = valeurs insérées par tp()
   - t(k,fb)   : texte dans la langue de S.lang, sinon anglais, sinon fb, sinon la clé
   - opName(k) : nom d'un opérateur ; cName() (app.js) gère les noms de chars (traduction FR seulement en français)
   Pour modifier un texte : changer la clé dans la langue voulue. Une clé absente retombe sur l'anglais. */
const LANG_META={
en:{name:'English',locale:'en-US'},ru:{name:'Русский',locale:'ru-RU'},de:{name:'Deutsch',locale:'de-DE'},es:{name:'Español',locale:'es-ES'},
fr:{name:'Français',locale:'fr-FR'},it:{name:'Italiano',locale:'it-IT'},pt:{name:'Português',locale:'pt-BR'},tr:{name:'Türkçe',locale:'tr-TR'},
ja:{name:'日本語',locale:'ja-JP'},ko:{name:'한국어',locale:'ko-KR'},'zh-CN':{name:'简体中文',locale:'zh-CN'},'zh-TW':{name:'繁體中文',locale:'zh-TW'}};

/* Langue du navigateur (navigator.languages puis navigator.language) ; chinois : Hant/TW/HK/MO → zh-TW, sinon zh-CN ; repli : en */
function detectLang(){
const L=(navigator.languages&&navigator.languages.length)?navigator.languages:[navigator.language||'en'];
for(const raw of L){const l=String(raw||'').toLowerCase().replace(/_/g,'-'),b=l.split('-')[0];
if(b==='zh')return /hant|-tw\b|-hk\b|-mo\b/.test(l)?'zh-TW':'zh-CN';
if(LANG_META.hasOwnProperty(b))return b}
return 'en'}

