/* Clés ind_* (industriels) et op_* (opérateurs) : noms propres identiques dans toutes les langues par défaut,
   générés depuis INDUSTRIES / OPS (data-game.js). Pour traduire un nom dans une langue : I18N.ja.op_mia='…' ici. */
Object.values(I18N).forEach(d=>{
Object.entries(INDUSTRIES).forEach(([k,v])=>{d['ind_'+k]=v});
Object.entries(OPS).forEach(([k,o])=>{d['op_'+k]=o.n})});

/* t(k,fb) : texte traduit (langue courante → anglais → fb → clé) ; tp(k,…) remplace {0},{1}… ; opName(k) : nom d'un opérateur */
function t(k,fb){const d=I18N[S.lang],e=I18N.en;return(d&&d[k])??(e&&e[k])??fb??k}
const tp=(k,...a)=>t(k).replace(/\{(\d+)\}/g,(_,i)=>a[i]??'');
function opName(k){return t('op_'+k,OPS[k]&&OPS[k].n)}
